# build_fig_2_15_uturns.R — Figure 2.17: government U-turns, 1979-2025
#
# ⚠ WHAT IS PLOTTED. PJ, 16 Aug 2026.
#   PANEL A, stacked bars = ALL U-turns per year (the headline measure), with the darker portion
#           the subset REVERSING POLICY ALREADY IN OPERATION (`in_force = yes`)
#   PANEL B, dots         = the subset that broke a MANIFESTO pledge, one dot per event
#
# ⛔ PANEL B USES THE STRICT DEFINITION (15 events), NOT the `manifesto_pledge` flag alone (24).
# PJ, 16 Aug. The flag was being set wherever the substance ALSO appeared in a manifesto, even when
# the commitment actually reversed was a speech, a White Paper, a named programme or a stated
# refusal — only 15 of the 24 carry `commitment_type = manifesto_pledge`. ⚠ And EIGHT of the nine
# loose cases fall after 1997, so the broad flag inflates the late period and makes the rise look
# about twice as steep as it is. Probable cause is the denominator again: recent manifestos are long
# and detailed, so a reversal of anything is likelier to have a manifesto sentence behind it.
# The broad count is retained in the series file as `n_manifesto_broad` and reported as robustness.
# The second line exists because of PJ's own objection to the whole section: "maybe U-turns are the
# normal business of government just to get out of minor jams, even Thatcher did it." A raw count
# cannot answer that. Reversing something already running is a different act from dropping a
# proposal, and the construct the chapter needs is COMMITMENT FAILURE - the capacity of the system
# to make a decision and hold it - not "changes of mind".
#
# ⛔ NOT the manifesto-starred subset, though the codebook first proposed it: 30 events and 28 of 47
# years at zero. A line through that shows the smoother's span parameter, not the politics. The
# starred events appear as DOTS in panel B — discrete marks, never a line — and as a named list
# in the appendix.
#
# ⛔ NOT `forced_by`: its `self` value is a residual ("none of the other four fit") that absorbs
# strike pressure early and would make the second line rise spuriously. Appendix table only.
#
# ⚠ COUNTED BY EVENT YEAR, NOT CHAPTER YEAR. PJ, 16 Aug: "a U-turn has to apply to the date it
# happened." The Register narrates reversals in the year it is REPORTING; six rows carried a
# reversal date earlier than their own chapter. Calendar year, verified: zero forward spill across
# 226 rows, so the chapters do end 31 December.
#
# ⚠ DEDUPLICATED. 250 coded rows -> 221 events: 26 merges (one government decision narrated more
# than once, within a chapter or across chapters years apart) and 3 adjudicated exclusions.
# 20 of the 26 merges fall pre-1997, so the correction is era-asymmetric and RUNS WITH the
# pre-registered expectation - which is why the uncorrected series is published alongside it in the
# appendix and named in the footnote. See DEDUPLICATION_RULE.md, POST_INSTRUMENT_LOG.md.
#
# ⛔ NO SMOOTHER. Considered and rejected: a LOESS through a count series that moves 0-10 a year
# would draw the reader's eye to a curve chosen by a span parameter, and the U-shape here is a
# claim about specific administrations, not a trend. The counts are shown as they are.
#
# ⚠ HOUSE STYLE. Greyscale (BUP). "Hard-boiled" = SPARE AND FACTUAL, not a clever hook:
#   "Figure 2.NN  <plain description>, <years>", figure number IN the title line, subtitle
# describes what is plotted and states no result, no statistics on the panel, no caption block.
# Source and every caveat go to the footnote. A figure informs; the text concludes.

suppressPackageStartupMessages({library(ggplot2); library(dplyr); library(readr); library(tidyr); library(patchwork)})

WS <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "../../..")) else getwd()
})
DW <- file.path(WS, "data_workspace_2026-07/policy_instability/uturns")

d <- read_csv(file.path(DW, "series/uturns_series.csv"), show_col_types = FALSE)

# ⚠ BARS, NOT TWO LINES — decided on the RENDER, not in the abstract. The first attempt drew both
# series as lines: 47 points each, moving 0-10 a year, crossing constantly. The result was
# unreadable as a pattern, and the shape the text needs to discuss was invisible in it. Counts of
# events are naturally bars, and because the in-force events are a SUBSET of the total, shading them
# inside the bar shows both quantities without a second jagged line and without any smoothing choice.
#
# ⛔ Still no smoother. The bars make the pattern legible without one, so a LOESS would only add a
# curve chosen by a span parameter.
long <- d |>
  mutate(rest = n - n_in_force) |>
  select(year, `Reversing policy already in operation` = n_in_force,
         `Abandoned before taking effect` = rest) |>
  pivot_longer(-year, names_to = "series", values_to = "value") |>
  mutate(series = factor(series, levels = c("Abandoned before taking effect",
                                            "Reversing policy already in operation")))

# ⚠ LABELS MOVED, 16 Aug — PJ: "labels are jarring, move the latter". At the upper LEFT they sat
# directly against the 1981 and 1993 bars, which both reach 10, so the text read as though it were
# annotating those years. They now sit in the genuinely dead space over the 1997-2013 trough, where
# no bar exceeds 8, and they annotate nothing by accident.
#
# ⚠ And the "Dark:" / "Light:" prefixes are gone. Naming a shade in words is a legend written out
# longhand; a small swatch in the matching grey IS the key, and it reads at a glance. ⛔ Do NOT set
# the label text itself in the two greys instead — light grey type on white is legible on screen and
# disappears in print, which is the wrong risk for a greyscale house style.
# ⚠ TWO PANELS — PJ, 16 Aug: "needs two panels with the dots underneath". On one panel the dots sat
# above the bars and had to be labelled "of which" to stop them reading as an addition to the total.
# Below the bars, in their own panel on a shared x axis, the subset relationship is carried by the
# layout instead of by a caveat in the key. Fewer words, less to misread.
#
# ⛔ NO BREAK TEST ON THIS FIGURE. PJ, 16 Aug: "no chows for this one given complexity." The series
# is U-shaped — high to 1996, a long trough, then a rise from 2015 — and a single-break test on a
# multi-turning-point series reports the strongest of several breaks as though it were the only one.
# RC06 records the same problem for the other Chapter 2 series. Turning points are described in the
# text from the administration means, not asserted from an F statistic.
#
# ⛔ Dots, not a line, in panel B: 14 events over 47 years, never more than two in a year. One dot
# per event.
#
# ⚠ AXIS LABEL IS "OF WHICH BROKE A MANIFESTO PLEDGE", NOT "MANIFESTO PLEDGES BROKEN", and the
# distinction is not pedantry. In the pledge-fulfilment literature "broken pledge" counts against a
# denominator of the WHOLE MANIFESTO and includes pledges simply never delivered. This panel counts
# only REVERSALS — a pledge quietly not acted on is not a U-turn and never enters the frame. Against
# the Comparative Party Pledges Project's coding of the same four Conservative manifestos, 76
# pledges were "not fulfilled" while this panel shows 3; but the book's own examples show why
# (1979 shipbuilding privatisation "was carried out by the next government" — delay, not reversal),
# and the one pledge it calls significant and abandoned for 1987, the poll tax, IS in this panel.
# ⛔ Do NOT quote the 3-against-76 as a capture rate: it compares "not fulfilled" with "reversed".

key <- data.frame(
  x   = 1997.6,
  y   = c(10.4, 9.4),
  lab = c("reversals of policy already in operation",
          "abandoned before taking effect"),
  fill = c("grey28", "grey78"))

base <- theme_minimal(base_size = 9) +
  theme(legend.position = "none",
        panel.grid.minor = element_blank(),
        panel.grid.major.x = element_blank(),
        panel.grid.major.y = element_line(colour = "grey90", linewidth = 0.3),
        # 17 Aug: this figure had TWO panels and no panel letters at all, the only multi-panel
        # figure in the chapter without them. House style = bold labs(tag=) 11 + italic grey30 9.
        plot.tag = element_text(face = "bold", size = 11),
        plot.subtitle = element_text(face = "italic", colour = "grey30", size = 9),
        axis.title.y = element_text(size = 8))

XS <- scale_x_continuous(breaks = seq(1980, 2025, 5), limits = c(1978.4, 2025.6))

pA <- ggplot(long, aes(year, value, fill = series)) +
  geom_col(width = 0.78, colour = NA) +
  geom_point(data = key, aes(x = x, y = y), shape = 22, size = 2.4, stroke = 0.3,
             fill = key$fill, colour = "grey45", inherit.aes = FALSE) +
  geom_text(data = key, aes(x = x + 0.9, y = y, label = lab),
            hjust = 0, size = 2.9, colour = "grey20", inherit.aes = FALSE) +
  scale_fill_manual(values = c("Abandoned before taking effect" = "grey78",
                               "Reversing policy already in operation" = "grey28")) +
  XS +
  scale_y_continuous(breaks = seq(0, 10, 2), limits = c(0, 11.2), expand = c(0, 0)) +
  # ⛔ The figure title used to be set HERE, on panel A, with two spaces instead of a colon and a
  #    hyphen instead of an en dash - unlike every other figure in the chapter. Moved to
  #    plot_annotation() below so the title sits above the whole figure, as elsewhere.
  labs(tag = "A", subtitle = "All U-turns, by year and type",
       x = NULL, y = "Number of U-turns") +
  base +
  theme(axis.text.x = element_blank())

dots <- d |>
  filter(n_manifesto > 0) |>
  rowwise() |>
  mutate(k = list(seq_len(n_manifesto))) |>
  tidyr::unnest(k)

pB <- ggplot(dots, aes(year, k)) +
  geom_point(shape = 21, size = 1.6, stroke = 0.45, fill = "white", colour = "grey15") +
  XS +
  scale_y_continuous(breaks = c(1, 2), limits = c(0.4, 2.6)) +
  labs(tag = "B", subtitle = "Of which broke a manifesto pledge",
       x = NULL, y = "Pledges broken") +
  base

fig <- pA / pB + patchwork::plot_layout(heights = c(3.1, 1)) +
  patchwork::plot_annotation(
    title    = "Figure 2.15: Government U-turns, 1979\u20132025",
    subtitle = "Commitments reversed by the government that made them.",
    theme    = theme(plot.title    = element_text(face = "bold", size = 12),
                     plot.subtitle = element_text(size = 9, colour = "grey30",
                                                  margin = margin(b = 8))))

out <- file.path(WS, "figures/fig_2_15_uturns_1979_2025.png")
ggsave(out, fig, width = 6.5, height = 4.0, dpi = 300, bg = "white")
cat("written", out, "\n")

# ── numbers for the TEXT and the footnote, never for the panel ───────────────────────────────────
era <- function(a, b) {
  s <- filter(d, year >= a, year <= b)
  sprintf("%-26s raw %4.1f/yr   in force %4.1f/yr   per 100k chars %5.2f",
          paste0(a, "-", b), mean(s$n), mean(s$n_in_force), mean(s$per_100k))
}
cat("\nfor the text, not the panel:\n")
for (p in list(c(1979, 1990), c(1991, 1996), c(1997, 2009), c(2010, 2016), c(2017, 2025)))
  cat("  ", era(p[1], p[2]), "\n")
cat(sprintf("\n  total events %d; reversing policy in force %d (%.0f%%)\n",
            sum(d$n), sum(d$n_in_force), 100 * sum(d$n_in_force) / sum(d$n)))
